package com.yuegang.zhihui.ai.api;import com.yuegang.zhihui.ai.application.*;import com.yuegang.zhihui.ai.security.*;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import java.io.*;import java.util.concurrent.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1/ai/chat")public final class ChatController{private final ChatService service;private final AiUserResolver users;public ChatController(ChatService s,AiUserResolver u){service=s;users=u;}@PostMapping ApiResponse<ChatResponse>chat(@Valid @RequestBody ChatRequest body,HttpServletRequest r){return ApiResponse.success(service.chat(users.resolve(r),body),TraceIdResolver.resolve(r));}@PostMapping(value="/stream",produces=MediaType.TEXT_EVENT_STREAM_VALUE)SseEmitter stream(@Valid @RequestBody ChatRequest body,HttpServletRequest r){long user=users.resolve(r);var emitter=new SseEmitter(120_000L);Thread.ofVirtual().name("ai-sse-").start(()->{try{ChatResponse response=service.chat(user,body);emitter.send(SseEmitter.event().name("meta").data(java.util.Map.of("conversationId",response.conversationId(),"messageId",response.messageId())));for(String token:response.answer().split("(?<=\\G.{24})"))emitter.send(SseEmitter.event().name("delta").data(token));emitter.send(SseEmitter.event().name("citations").data(response.citations()));emitter.send(SseEmitter.event().name("done").data(java.util.Map.of("refused",response.refused())));emitter.complete();}catch(Exception e){emitter.completeWithError(e);}});return emitter;}}
